<script setup>import{computed,ref}from'vue';import data from '../experiments/artifacts/10/hierarchy_sweep.json';const ids=Object.keys(data.variants),selected=ref('baseline'),v=computed(()=>data.variants[selected.value]);const pct=(value,max)=>`${Math.round(value/max*100)}%`</script>
<template><section class="compare arch-overlay"><nav><button v-for="id in ids" :key="id" :class="{on:selected===id}" @click="selected=id">{{id}}</button></nav><div class="bars"><div><span>DRAM bytes</span><i class="mem" :style="{width:pct(v.dram_bytes,1024)}"/><b>{{v.dram_bytes}}</b></div><div><span>Queue depth</span><i :style="{width:pct(v.queue_depth,24)}"/><b>{{v.queue_depth}}</b></div><div><span>Stall cycles</span><i class="stall" :style="{width:pct(v.stall_cycles,192)}"/><b>{{v.stall_cycles}}</b></div></div><footer><code>artifact 10 · {{selected}}</code><strong>{{(v.normalized_performance*100).toFixed(1)}}% normalized perf</strong></footer></section></template>
<style scoped>.compare{right:0;bottom:0;width:650px;padding:18px 21px;border-radius:20px}.compare nav{display:flex;gap:7px}.compare button{font-size:10px;padding:5px 9px}.compare button.on{background:#087d99;color:#fff}.bars{display:grid;gap:13px;margin:17px 0}.bars div{display:grid;grid-template-columns:82px 1fr 40px;align-items:center;gap:9px;color:#adc3d8;font-size:10px}.bars i{height:12px;background:#17d9ff;border-radius:8px;box-shadow:0 0 10px #17d9ff66}.bars i.mem{background:#b9ff33}.bars i.stall{background:#f16bb5}.compare footer{display:flex;justify-content:space-between;color:#adc3d8;font-size:10px}.compare footer strong{color:#ffbe00}</style>
